/* ---------- Donut chart ---------- */
/* where the agent's time went this week, as a gauge (owner, 21 Nov): a half ring of parts in the
   chart palette's saturated colours, in order, with small gaps and slightly rounded corners, and the rest of the week's budget
   as a light grey track. The total sits in the middle with what it is out of, and the legend under the gauge names each part
   with a bar of its colour and its hours. Pointing at a part or a row, or the keyboard on a row, lights both and puts that part
   in the middle; a click on either (or Enter on a row) selects it, so it stays in the middle with its row filled until it is
   clicked again or Escape clears it. A quiet head: the title with a hairline under it. The content sits 16px in from every
   edge; each row's mark and hours sit on the content's edges, its hover a quiet fill that reaches out round them */
.dm-dnx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent);--dm-dnx-track:var(--dm-chip);--dm-dnx-th:18;--dm-dnx-cr:4}
.dm-dnx-h{padding-bottom:var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px;line-height:17px;color:var(--dm-fg)}
.dm-dnx-g{position:relative;width:220px;max-width:100%;margin:var(--dm-s-1) auto 0}
.dm-dnx-svg{display:block;width:100%;height:auto;overflow:visible}
.dm-dnx-svg path{stroke-linejoin:round;transition:opacity var(--dm-t-fast) var(--dm-ease);cursor:default}
/* (a page that draws its own parts gives them their own stroke-width) */
.dm-dnx-svg path:not([stroke-width]){stroke-width:calc(var(--dm-dnx-cr) * 2px)}
.dm-dnx-svg .dm-tr{fill:var(--dm-dnx-track);stroke:var(--dm-dnx-track);cursor:auto}
.dm-dnx-g.dm-hov path:not(.dm-hl,.dm-tr){opacity:.3}
.dm-dnx-c{position:absolute;left:0;right:0;bottom:0;display:flex;flex-direction:column;align-items:center;pointer-events:none}
.dm-dnx-c b{font-size:14px;line-height:20px;font-weight:500;letter-spacing:-.01em;color:var(--dm-fg)}
.dm-dnx-c span{font-size:12px;line-height:16px}
/* the last row's words end 16px from the card's foot, its hover fill reaching out round them */
.dm-dnx-lg{position:relative;display:flex;flex-direction:column;gap:2px;margin:0 calc(-1 * var(--dm-s-2)) calc(-1 * var(--dm-s-2))}
.dm-dnx-r{position:relative;display:flex;align-items:center;gap:var(--dm-s-2);width:100%;padding:6px var(--dm-s-2);border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;line-height:20px;text-align:left;transition:background-color var(--dm-t-fast) var(--dm-ease)}
.dm-dnx-r.dm-hl{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-dnx-r:hover{background:var(--dm-row)}}
.dm-dnx-r.dm-sel{background:color-mix(in srgb,var(--dm-fg) 9%,transparent)}
.dm-dnx-r.dm-sel .dm-t{color:var(--dm-fg)}
.dm-dnx-svg path[data-i]{cursor:pointer}
/* the hover that glides from row to row is Clean's (below); the other styles fill the row itself */
.dm-dnx-hv{display:none}
.dm-dnx-r:focus-visible{outline-offset:-2px}
.dm-dnx-r i{width:3px;height:14px;border-radius:2px;flex:none}
.dm-dnx-r .dm-t{flex:1;min-width:0;color:var(--dm-fg2)}
.dm-dnx-r .dm-v{color:var(--dm-fg)}
/* Blueprint: square corners on the parts and the track */
:root:not([data-style="soft"],[data-style="clean"]) .dm-dnx-svg path:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){stroke-linejoin:miter}
/* Clean (owner, 21 Nov: "it definitely has to be updated"): the title on an off-white head strip that follows the card's
   corners; a slimmer ring (14px against Soft's 18) with a little rounder corners (5px against 4); the track recessed with
   Clean's inner shadow (an SVG filter, since a path takes no inset box-shadow); the legend
   Clean's 10px rows with its one hover, a neutral fill that eases in over 220ms and glides from row to
   row (it only fades with reduced motion), and the selected row a stronger fill of the same shape. The middle's figure is set
   with tabular figures and Clean's tighter tracking. In Clean dark the accent is white (owner, 21 Nov; Clean dark's tokens),
   so the first part is white; the other parts keep the palette's hues */
