:root[data-style="clean"] .dm-dnx-h,:root [data-style="clean"] .dm-dnx-h,:root [data-style="clean"].dm-dnx-h{margin:calc(-1 * var(--dm-s-4)) calc(-1 * var(--dm-s-4)) 0;padding:calc(var(--dm-strip-y) + 4px) var(--dm-s-4);background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0;font-size:13px;line-height:20px;font-weight:500}
