:root[data-style="clean"] .dm-dnx-r,:root [data-style="clean"] .dm-dnx-r,:root [data-style="clean"].dm-dnx-r{border-radius:var(--dm-r-in)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-dnx-lg.dm-gl .dm-dnx-r:is(:hover,.dm-hl),:root [data-style="clean"] .dm-dnx-lg.dm-gl .dm-dnx-r:is(:hover,.dm-hl),:root [data-style="clean"].dm-dnx-lg.dm-gl .dm-dnx-r:is(:hover,.dm-hl){background:transparent}}
:root[data-style="clean"] .dm-dnx-r.dm-sel,:root [data-style="clean"] .dm-dnx-r.dm-sel,:root [data-style="clean"].dm-dnx-r.dm-sel,:root[data-style="clean"] .dm-dnx-lg.dm-gl .dm-dnx-r.dm-sel,:root [data-style="clean"] .dm-dnx-lg.dm-gl .dm-dnx-r.dm-sel,:root [data-style="clean"].dm-dnx-lg.dm-gl .dm-dnx-r.dm-sel{background:color-mix(in srgb,var(--dm-fg) 11%,var(--dm-surface))}
